// Источник: web-тест .qa/e2e/tests/important-dates/id-04-calendar-month-year-picker.spec.ts, план .qa/e2e/specs/important-dates.md (17.4), кейс .qa/tests/important-dates/ID-04-calendar-month-year-picker.md
// Тикет #6a86f7e0. Опора: AC1, AC5; реджект 14.09 (ответ 15.09), реджект 29.09 (ответ 30.09 — без ручного ввода); Figma 454:11002.
// Окно закрывается без сохранения. «Сегодня» — реальная дата устройства; ожидаемые строки вычисляются (на 3.10.2026 = строки кейса).
import { $$, driver, expect } from '@wdio/globals';
import { byLabel, byLabelStartsWith, byText, byTextContains, tapLabel, tapText, expectVisibleText, expectTextContains, swipeUp } from '../../helpers/ui.ts';
import { goTab } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';
import { daysInMonth, gregMonthName, hebrewDayMonth, hebrewMonthRange, isoDate } from '../../../e2e/tests/_helpers/dates.ts';

const MONTHS = ['ינואר', 'פברואר', 'מרץ', 'אפריל', 'מאי', 'יוני', 'יולי', 'אוגוסט', 'ספטמבר', 'אוקטובר', 'נובמבר', 'דצמבר'];
/** Все ячейки-дни (подпись «YYYY-MM-DD, <еврейская дата>»). */
const dayCells = () => (driver.isAndroid
  ? $$('android=new UiSelector().descriptionMatches("\\\\d{4}-\\\\d{2}-\\\\d{2}, .+")').getElements()
  : $$('-ios predicate string:name MATCHES "\\\\d{4}-\\\\d{2}-\\\\d{2}, .+"').getElements());

describe('Важные даты и אזכרות', () => {
  afterEach(async () => { await toHome(); });

  it('ID-04 Календарь в окне даты — дни текущего месяца, двойной еврейский заголовок, выбор месяца/года, без ручного ввода #6a86f7e0 @prod-safe', async () => {
    const today = new Date();
    const Y = today.getFullYear();
    const M = today.getMonth();
    const curTitle = `${gregMonthName(Y, M)} ${Y}`;
    const pY = M === 0 ? Y - 1 : Y;
    const pM = M === 0 ? 11 : M - 1;
    const prevTitle = `${gregMonthName(pY, pM)} ${pY}`;
    const iso = (y: number, m0: number, d: number) => isoDate(new Date(y, m0, d, 12));

    // 1. «בית» → «הוספת תאריך חשוב» → «אזכרה».
    await goTab('בית');
    const add = await byLabel('הוספת תאריך חשוב');
    for (let i = 0; i < 8 && !(await add.isDisplayed().catch(() => false)); i++) await swipeUp();
    await add.click();
    await tapText('אזכרה');

    // 2. Текущий месяц: заголовок, двойной еврейский заголовок, все дни с еврейской датой, соседние месяцы — без чисел.
    await expect(byLabel(`${curTitle}: בחירת שנה וחודש`)).toBeDisplayed();
    await expectTextContains(hebrewMonthRange(Y, M));
    const curDays = daysInMonth(Y, M);
    expect((await dayCells()).length).toBe(curDays);
    for (let d = 1; d <= curDays; d++) await expect(byLabelStartsWith(`${iso(Y, M, d)}, `)).toBeExisting();
    await expect(byLabelStartsWith(`${iso(Y, M, 1)}, ${hebrewDayMonth(new Date(Y, M, 1, 12))}`)).toBeExisting();

    // 3. Выбор месяца/года: год, «השנה הקודמת»/«השנה הבאה», 12 месяцев, «חזרה ללוח» → предыдущий месяц.
    await tapLabel(`${curTitle}: בחירת שנה וחודש`);
    await expect(byLabel(`${Y}: בחירת שנה אחרת`)).toBeDisplayed();
    await expect(byLabel('השנה הקודמת')).toBeDisplayed();
    await expect(byLabel('השנה הבאה')).toBeDisplayed();
    for (const m of MONTHS) await expect(byLabelStartsWith(`${m} ${Y}`)).toBeDisplayed();
    await expectVisibleText('חזרה ללוח');
    await tapLabel('השנה הקודמת');
    await tapLabel('השנה הבאה');                       // в прошлом году «השנה הבאה» активна
    if (pY !== Y) await tapLabel('השנה הקודמת');      // январь → декабрь прошлого года
    await tapLabel(prevTitle);

    await expectVisibleText(prevTitle);
    await expectTextContains(hebrewMonthRange(pY, pM));
    const prevDays = daysInMonth(pY, pM);
    expect((await dayCells()).length).toBe(prevDays);
    await expect(byLabelStartsWith(`${iso(pY, pM, 1)}, `)).toBeExisting();
    await expect(byLabelStartsWith(`${iso(pY, pM, prevDays)}, `)).toBeExisting();

    // Без ручного ввода: нет «או הקלידו…» и «מעבר».
    await expect(byTextContains('או הקלידו')).not.toBeDisplayed();
    await expect(byText('מעבר')).not.toBeDisplayed();

    // 4. «סגירה» без сохранения.
    await tapLabel('סגירה');
    await expect(byLabelStartsWith(`${prevTitle}: `)).not.toBeDisplayed();
  });
});
